import json,re
async def s(q,n=5,w=300):
    r=await web_search({"query":q})
    if isinstance(r,str): r=json.loads(r)
    print("##",q)
    for i,x in enumerate(r[:n]):
        print(i,x['url'],x.get('page_age'),len(x['content']))
    return r
