def grep(r,pat,w=200,maxn=8):
    for i,x in enumerate(r):
        for m in list(re.finditer(pat,x['content']))[:maxn]:
            print(i,"...",x['content'][max(0,m.start()-w):m.end()+w].replace("\n"," "))
            print('--')
